using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using PawPuff.Models;
namespace PawPuff.Controllers;
public class AccountController(UserManager<ApplicationUser> users,SignInManager<ApplicationUser> signIn) : Controller {
 [HttpGet] public IActionResult Register()=>View();
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Register(string email,string password,string displayName,string role="Buyer"){if(role!="Buyer"&&role!="Seller")role="Buyer";if(string.IsNullOrWhiteSpace(displayName)||string.IsNullOrWhiteSpace(email)||string.IsNullOrWhiteSpace(password)){ModelState.AddModelError("","Please fill in every field.");return View();}var user=new ApplicationUser{UserName=email,Email=email,DisplayName=displayName};var result=await users.CreateAsync(user,password);if(result.Succeeded){await users.AddToRoleAsync(user,role);await signIn.SignInAsync(user,false);return RedirectToAction("Index",role=="Seller"?"Seller":"Home");}foreach(var e in result.Errors)ModelState.AddModelError("",e.Description);return View();}
 [HttpGet] public IActionResult Login(string? returnUrl=null){ViewBag.ReturnUrl=returnUrl;return View();}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Login(string email,string password,string? returnUrl=null){var user=await users.FindByEmailAsync(email);var result=user is null?Microsoft.AspNetCore.Identity.SignInResult.Failed:await signIn.PasswordSignInAsync(user.UserName!,password,false,false);if(result.Succeeded){if(user!=null){if(await users.IsInRoleAsync(user,"Admin"))return RedirectToAction("Index","Admin");if(await users.IsInRoleAsync(user,"Seller"))return RedirectToAction("Index","Seller");}return LocalRedirect(string.IsNullOrEmpty(returnUrl)?"/":returnUrl);}ModelState.AddModelError("","Invalid email or password.");ViewBag.ReturnUrl=returnUrl;return View();}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Logout(){await signIn.SignOutAsync();return RedirectToAction("Index","Home");}
 public IActionResult Denied()=>Content("Access denied. Your account does not have permission to view this page.");
}
